fn solve(n: i8, s: Vec<char>) -> i8 {
    // Count the number of indices k where s[k] == s[k+1]
    // Only check up to n-2 because we compare s[k] with s[k+1]
    let mut count = 0;
    for k in 0..(n - 1) {
        // Convert k to usize because indexing Vec requires usize
        let idx = k as usize;
        if s[idx] == s[idx + 1] {
            count += 1;
        }
    }
    count
}